counterexample:
INSERT INTO t1 (c1, c2) VALUES ('Corona', 'info1');
INSERT INTO t1 (c1, c2) VALUES ('a', 'info2');

INSERT INTO t2 (c1, c2) VALUES ('Corona', 'info3');

INSERT INTO t3 (c1, c2) VALUES ('a', 'info4');

-- t4: uses t4.c1 = 'a' (must exist in t3) and t4.c2 = 'Corona' (must exist in t1)
INSERT INTO t4 (c1, c2, c3) VALUES ('a', 'Corona', 1);

-- t5: must join with t4 naturally, so t5.c1 = 'a' and t5.c2 = 'Corona'. Note that t5.c1 references t1 and t5.c2 references t2.
INSERT INTO t5 (c1, c2, c3) VALUES ('a', 'Corona', 1.00);

-- t6: Do not insert any row for candidate 'a'. Any row with c1 = 'a' and c2 = 'Corona' or any other value is omitted.
-- This ensures that Q1 sees 'a' (since there is no t6 row with c2 = 'Corona') but Q2 fails to join 'a' with a t6 row satisfying t6.c2 <> 'Corona'.

