counterexample:
INSERT INTO t1 (c1, c2) VALUES ('A', 'dummy1');

INSERT INTO t2 (c1, c2) VALUES ('Amstel', 'dummy2');

-- In t5, insert a row with c2 = 'Amstel' and c3 > 2, which qualifies Q2
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'Amstel', 3);

-- Do not insert any matching row into t4. This way, the NATURAL JOIN in Q1 will yield no row, so Q1 returns an empty result, whereas Q2 returns 'A'.

