counterexample:
-- Insert rows for supporting tables

-- t1: referred to by t4.c2 and t5.c1
INSERT INTO t1 (c1, c2) VALUES ('Corona', 'dummy');
INSERT INTO t1 (c1, c2) VALUES ('A', 'dummy');

-- t2: referred to by t5.c2 and t6.c2
INSERT INTO t2 (c1, c2) VALUES ('Corona', 'dummy');
INSERT INTO t2 (c1, c2) VALUES ('NotCorona', 'dummy');

-- t3: referred to by t4.c1 and t6.c1
INSERT INTO t3 (c1, c2) VALUES ('A', 'dummy');
INSERT INTO t3 (c1, c2) VALUES ('B', 'dummy');

-- t4: row with c1 = 'A' and c2 = 'Corona' (c1 references t3 and c2 references t1)
