counterexample:
-- Insert data for table t1 (referenced by t4 and t5)
INSERT INTO t1 (c1, c2) VALUES ('B', 'dummyB');
INSERT INTO t1 (c1, c2) VALUES ('C', 'dummyC');

-- Insert data for table t2 (referenced by t5 and t6)
INSERT INTO t2 (c1, c2) VALUES ('D', 'dummyD');
INSERT INTO t2 (c1, c2) VALUES ('E', 'dummyE');

-- Insert data for table t3
INSERT INTO t3 (c1, c2) VALUES ('A', 'A2');

-- Insert data for table t4 (must reference t3 and t1)
INSERT INTO t4 (c1, c2, c3) VALUES ('A', 'B', 1);

-- Insert data for table t5 (must reference t1 and t2)
-- t5 row that participates in the join: t5.c1 = 'B' matching t4.c2
INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'D', 1.23);
-- Extra t5 row that is not joined with any t4 row for t3 'A'
INSERT INTO t5 (c1, c2, c3) VALUES ('C', 'E', 2.34);

-- Insert data for table t6 (must reference t3 and t2)
-- Providing the match so that the joined t5 row satisfies the condition in Q1
INSERT INTO t6 (c1, c2) VALUES ('A', 'D');

