);

counterexample:
-- t1: primary key on c1
INSERT INTO t1 (c1, c2) VALUES ('A', 'dummy'), ('B', 'dummy');

-- t2: primary key on c1
INSERT INTO t2 (c1, c2) VALUES ('X', 'dummy');

-- t3: primary key on c1
INSERT INTO t3 (c1, c2) VALUES ('B1', 'dummy'), ('B2', 'dummy');

-- t4: (c1, c2, c3); f.c1 references t3 and f.c2 references t1
INSERT INTO t4 (c1, c2, c3) VALUES ('B1', 'A', 10), ('B2', 'B', 20);

-- t5: (c1, c2, c3); c1 references t1 and c2 references t2
-- Two rows in t5 with the same c2 ('X') but different c1 values ('A' and 'B')
INSERT INTO t5 (c1, c2, c3) VALUES ('A', 'X', 100.00), ('B', 'X', 300.00);

-- t6: (c1, c2) where c1 from t3 and c2 from t2
-- Choose c2 = 'X' so that alias1 will produce rows (A, 'X') and (B, 'X'), causing the join in Q2 to require t5 rows with c1 = 'X' as well
INSERT INTO t6 (c1, c2) VALUES ('B1', 'X'), ('B2', 'X');

