INSERT INTO t5 (c1, c2, c3) VALUES ('B', 'y', 1.00);

-- Under these inserts:
-- Q1 will check that for t1='A', its t5 set {x} is a proper subset of t5 set for t1='B' {x,y}, returning the pair (A,B).
-- Q2, however, produces distinct pairs from t5 rows based on the c1 values with condition alias3.c1 > alias4.c1, which will yield (B,A) if 'B' > 'A'.
-- Thus, the two queries do not return the same result.

